UPDATE `camera_device`
device_id = #{deviceId}, plot_id = #{plotId}, name = #{name}, stream_protocol = #{streamProtocol}, stream_url = #{streamUrl}, snapshot_url = #{snapshotUrl}, resolution = #{resolution}, online_status = #{onlineStatus}, direction = #{direction},
WHERE id = #{id}

UPDATE `camera_device` c
JOIN `plot` p ON p.id = c.plot_id
SET c.direction = #{direction}
WHERE c.id = #{id} AND p.user_id = #{userId}

