SELECT 
FROM `camera_device` c



        AND p.user_id = #{userId}


        AND c.plot_id = #{plotId}


        AND p.plot_name LIKE CONCAT('%', #{plotName}, '%')


        AND c.name LIKE CONCAT('%', #{name}, '%')


        AND c.stream_protocol = #{streamProtocol}


        AND c.online_status = #{onlineStatus}


ORDER BY c.id DESC

SELECT FROM `camera_device` c
WHERE p.user_id = #{userId}
AND c.plot_id = #{plotId}
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR p.plot_name LIKE CONCAT('%', #{keyword}, '%') OR cr.crop_name LIKE CONCAT('%', #{keyword}, '%'))
